837	    fn collect_completion(
838	        config: &SimulatedEngineConfig,
839	        req: Request,
840	    ) -> (Vec<u32>, Option<usize>, Terminal) {
841	        let mut engine = start_engine(config);
842	        assert_eq!(engine.schedulers.len(), 1);
843	        let mut partition = engine.schedulers.remove(0);
844	        let mut steps = partition.handle.take_steps().expect("step stream");
845	        let _control = partition.handle.submit(req);
846	
847	        let mut tokens = Vec::new();
848	        let mut prompt_tokens = None;
849	        let mut terminal = None;
850	        while terminal.is_none() {
851	            let step = steps.blocking_recv().expect("step message");
852	            for update in step.updates {
853	                if let Some(scheduled) = update.scheduled {
854	                    prompt_tokens = Some(scheduled.prompt_tokens);
855	                }
856	                tokens.extend(update.tokens);
857	                if let Some(t) = update.terminal {
858	                    terminal = Some(t);
859	                }
860	            }
861	        }
862	        drop(partition.handle);
863	        partition.join.join().expect("driver thread exits");
864	        (tokens, prompt_tokens, terminal.expect("terminal"))
865	    }
